export default function Sidebar({ className = "" }) {
  const location = useLocation()
  const navigate = useNavigate()

  const navItems = [
    {
      name: 'Dashboard',
      path: '/dashboard',
      icon: DashboardIcon,
    },
    {
      name: 'Materi',
      path: '/materi',
      icon: MateriIcon,
    },
    {
      name: 'Latihan & Kuis',
      path: '/latihan',
      icon: LatihanIcon,
    },
    {
      name: 'Riwayat & Diagnostik',
      path: '/diagnostic',
      icon: DiagnosticIcon,
    },
    {
      name: 'Pengaturan Profil',
      path: '/profile',
      icon: ProfileSettingsIcon,
    },
  ]

  const handleLogout = () => {
    // Navigasi ke login
    navigate('/login')
  }

  return (
    <aside
      className={`w-72 min-h-screen bg-white shadow-[0px_1px_16px_rgba(108,92,231,0.06)] border-r border-[#EEF5F7] px-4 py-6 flex flex-col justify-between font-['Plus_Jakarta_Sans'] select-none ${className}`}
      style={{ minHeight: '100vh', width: '288px' }}
    >
      {/* Top Section */}
      <div className="flex flex-col gap-6">
        {/* Brand / Logo */}
        <Link to="/dashboard" className="px-3 flex items-center gap-3 group">
          <div className="w-8 h-8 rounded-lg bg-[#6C5CE7] flex items-center justify-center p-1 shadow-sm transition-transform group-hover:scale-105">
            <img
              src={logoIcon}
              alt="Mindora Logo"
              className="w-6 h-4.5 object-contain"
            />
          </div>
          <span className="text-[#6C5CE7] font-['Rubik'] font-extrabold text-2xl leading-9 tracking-tight">
            Mindora
          </span>
        </Link>

        {/* Navigation Menus */}
        <nav className="flex flex-col gap-1.5" aria-label="Menu Utama">
          {navItems.map((item) => {
            const IconComponent = item.icon
            const isActive = location.pathname === item.path

            return (
              <Link
                key={item.name}
                to={item.path}
                className={`px-3.5 py-3 rounded-xl flex items-center gap-3 text-sm font-medium transition-all duration-200 ${
                  isActive
                    ? 'bg-[#6C5CE7] text-[#FAF6FF] shadow-[0px_4px_16px_rgba(108,92,231,0.20)]'
                    : 'text-[#474554] hover:bg-[#F4FAFD] hover:text-[#5341CD]'
                }`}
              >
                <div
                  className={`flex items-center justify-center transition-colors ${
                    isActive ? 'text-[#FAF6FF]' : 'text-[#474554]'
                  }`}
                >
                  <IconComponent />
                </div>
                <span className="leading-[22px]">{item.name}</span>
              </Link>
            )
          })}
        </nav>
      </div>

      {/* Bottom Section */}
      <div className="flex flex-col gap-4 mt-6">
        {/* Card Status Belajar */}
        <div className="bg-[#EEF5F7] rounded-2xl p-4 shadow-[0px_4px_20px_rgba(108,92,231,0.06)] flex flex-col gap-2.5">
          <div className="flex justify-between items-center">
            <span className="text-[#5341CD] text-[11px] font-bold uppercase tracking-[0.55px] leading-3.5">
              Status Belajar
            </span>
            <div className="flex items-center justify-center">
              <BadgeAwardIcon />
            </div>
          </div>

          <div className="flex flex-col">
            <h4 className="text-[#161D1F] text-lg font-bold leading-[26px]">
              Level 3
            </h4>
            <p className="text-[#474554] text-xs font-normal leading-[18px]">
              Siswa Adaptif Mandiri
            </p>
          </div>

          {/* Progress Bar */}
          <div className="h-2 w-full bg-[#DDE4E6] rounded-full overflow-hidden relative">
            <div
              className="h-full bg-[#6C5CE7] rounded-full transition-all duration-500 ease-out"
              style={{ width: '65%' }}
            />
          </div>

          <p className="text-[#474554] text-[11px] font-bold leading-3.5 tracking-[0.44px]">
            65% menuju Level 4
          </p>
        </div>

        {/* Footer Actions: Pusat Bantuan & Keluar */}
        <div className="px-2 flex items-center justify-between text-[#474554] text-xs font-normal">
          <button
            type="button"
            className="flex items-center gap-2 hover:text-[#5341CD] transition-colors cursor-pointer py-1"
          >
            <HelpIcon />
            <span>Pusat Bantuan</span>
          </button>

          <button
            type="button"
            onClick={handleLogout}
            className="flex items-center gap-1.5 hover:text-red-500 transition-colors cursor-pointer py-1"
          >
            <LogoutIcon />
            <span>Keluar</span>
          </button>
        </div>
      </div>
    </aside>
  )
}
